import { type CommentSpan } from "../findCommentSpans/index.ts";
import type { InlineCommentSpan } from "../findInlineCommentSpans/index.ts";
/**
 * Writes the second slash of every `//` that opens no comment as `?`, so a reader that knows less than {@link findCommentSpans} cannot take it for a comment.
 *
 * `style-search` reads a `//` anywhere, `url(http://x/y.png)` included, as a comment to the end of the line, so its count of open parentheses never comes back down; the pattern `functionCommaSpaceChecker` maps indexes with reads it the same way. A `?` is a character no reading of the copy gives a meaning to; a hyphen would turn `//-(` into `/--(`, an identifier. Positions hold. A slash a comment opens on is left alone whichever of the two it is: `*\/` closing one comment and `/*` opening the next spell a `//` between them.
 * @param text - The value or file to copy.
 * @param spans - The comment spans of the text, both kinds, where known; a span left out leaves its slash unguarded.
 * @returns The text with every false opening masked.
 */
export declare function hideFalseInlineComments(text: string, spans?: (CommentSpan | InlineCommentSpan)[]): string;
